 id varchar(36) NOT NULL PRIMARY KEY, slot tinyint NOT NULL UNIQUE CHECK (slot=1),
 name varchar(100) NOT NULL, website varchar(500) NOT NULL, short_description varchar(300) NOT NULL,
 business_type varchar(100) NOT NULL, country varchar(80) NOT NULL, timezone varchar(80) NOT NULL, summary varchar(600) NOT NULL,
 active boolean NOT NULL CHECK (active IN (0,1)), approved boolean NOT NULL CHECK (approved IN (0,1)),
 sort_order int NOT NULL CHECK (sort_order BETWEEN 0 AND 999),
 revision int NOT NULL DEFAULT 1 CHECK (revision > 0), updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
